static int[] dijkstra(List<int[]>[] g, int n, int src) {
  int[] dist = new int[n];
  Arrays.fill(dist, Integer.MAX_VALUE); dist[src] = 0;
  PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> Integer.compare(a[0], b[0]));
  pq.add(new int[]{0, src});
  while (!pq.isEmpty()) {
    int[] top = pq.poll(); int d = top[0], u = top[1];
    if (d > dist[u]) continue;
    for (int[] e : g[u]) if (d + e[1] < dist[e[0]]) { dist[e[0]] = d + e[1]; pq.add(new int[]{dist[e[0]], e[0]}); }
  }
  return dist;
}

static int cheapest(int n, int[][] flights, int src, int dst, int k) {
  int INF = Integer.MAX_VALUE / 2;
  int[] dist = new int[n];
  Arrays.fill(dist, INF); dist[src] = 0;
  for (int i = 0; i <= k; i++) {
    int[] nxt = dist.clone();
    for (int[] f : flights)
      if (dist[f[0]] + f[2] < nxt[f[1]]) nxt[f[1]] = dist[f[0]] + f[2];
    dist = nxt;
  }
  return dist[dst] >= INF ? -1 : dist[dst];
}

static int[][] floyd(int[][] dist) {
  int n = dist.length;
  for (int k = 0; k < n; k++)
    for (int i = 0; i < n; i++)
      for (int j = 0; j < n; j++)
        if (dist[i][k] + dist[k][j] < dist[i][j]) dist[i][j] = dist[i][k] + dist[k][j];
  return dist;
}
